
const start=document.getElementById('start-pane'),result=document.getElementById('result-pane');
function show(which){const made=which==='result';start.classList.toggle('active',!made);result.classList.toggle('active',made);document.getElementById('show-start').classList.toggle('active',!made);document.getElementById('show-result').classList.toggle('active',made);document.getElementById('step-one').className='step '+(made?'done':'active');document.getElementById('step-two').className='step '+(made?'done':'');document.getElementById('step-three').className='step '+(made?'active':'');}
document.getElementById('show-start').addEventListener('click',()=>show('start'));document.getElementById('show-result').addEventListener('click',()=>show('result'));document.getElementById('upload-demo').addEventListener('click',()=>show('result'));document.getElementById('existing-demo').addEventListener('click',()=>show('result'));document.getElementById('replace-demo').addEventListener('click',()=>show('start'));
document.querySelectorAll('.preset').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.preset').forEach(item=>item.classList.remove('active'));button.classList.add('active');document.querySelector('.chosen').textContent='已选择：'+button.querySelector('strong').textContent+' · 可继续替换元素';}));
document.querySelectorAll('.choose-shot').forEach((button,index)=>button.addEventListener('click',()=>{document.querySelectorAll('.shot').forEach(item=>item.classList.remove('selected'));document.querySelectorAll('.shot')[index].classList.add('selected');document.querySelector('.inspector .eyebrow').textContent='正在调整第 '+String(index+1).padStart(2,'0')+' 句';}));

